const root=document.getElementById('property');fetch('properties.json').then(r=>r.json()).then(list=>{const p=list.find(p=>p.published===true&&p.id===new URLSearchParams(location.search).get('id'));if(!p)return;root.replaceChildren();for(const [tag,value] of [['span',p.city],['h1',p.name],['p',p.description],['p',`${p.guests} voyageurs · ${p.bedrooms} chambres · ${p.bathrooms} salles de bain`]]){const e=document.createElement(tag);e.textContent=value;root.append(e)}for(const src of p.photos||[]){const u=new URL(src,location.href);if(u.protocol!=='https:'&&u.origin!==location.origin)continue;const img=document.createElement('img');img.src=u.href;img.alt=p.name;img.style.cssText='width:100%;max-height:600px;object-fit:cover';root.append(img)}const amenities=document.createElement('p');amenities.textContent=(p.amenities||[]).join(' · ');root.append(amenities);if(p.bookingUrl){const u=new URL(p.bookingUrl);if(u.protocol==='https:'){const a=document.createElement('a');a.href=u.href;a.className='button';a.textContent='Voir les disponibilités et le prix';root.append(a)}}else{const n=document.createElement('p');n.textContent='Les réservations ne sont pas encore ouvertes.';root.append(n)}const guide=document.createElement('a');guide.href='guide-toulouse.html';guide.textContent='Notre guide de Toulouse';guide.style.display='block';if(p.city==='Toulouse')root.append(guide)}).catch(()=>{});
